"use client";
import React, { useState } from "react";
import { X, Check, Loader2, CheckCircle2, XCircle } from "lucide-react";
import { shipmentsApi } from "../services/shipmentsApi";
import { toast } from "sonner";
import BusinessReference from "@/components/common/BusinessReference";
import { useEscapeKey } from "@/hooks/useEscapeKey";
import {
  isFreightAllocatedForShipment,
  isFreightRequiredForShipment,
} from "../utils/freightRuleEngine";

const WORKFLOW_STATUSES = [
  "Scheduled",
  "Ready",
  "Stuffing",
  "Dispatched",
  "In Transit",
  "At Port",
  "Sailed",
  "Arrived",
  "Delivered",
  "Cancelled"
];

export default function ShipmentEditModal({ shipment, isOpen, onClose, onSaveSuccess }) {
  useEscapeKey(onClose, isOpen && Boolean(shipment));

  const [prevShipmentId, setPrevShipmentId] = useState(shipment?.id);
  const [form, setForm] = useState(() => ({
    shipmentDate: shipment?.shipmentDate || "",
    noOfContainers: shipment?.noOfContainers || "",
    quantity: shipment?.quantity || "",
    ratePerMt: shipment?.ratePerMt || "",
    purchaseRate: shipment?.purchaseRate || "",
    forex: shipment?.forex || "",
    freight: isFreightRequiredForShipment(shipment) ? (shipment?.freight ?? "") : "",
    freightCurrency: shipment?.freightCurrency || shipment?.salesContract?.currencyCode || "",
    freightDescription: shipment?.freightDescription || "",
    status: shipment?.status || "Scheduled",
    remarks: shipment?.remarks || "",
    shipmentNo: shipment?.shipmentNo || ""
  }));
  
  const [isSaving, setIsSaving] = useState(false);
  const [errors, setErrors] = useState({});

  if (shipment && shipment.id !== prevShipmentId) {
    setPrevShipmentId(shipment.id);
    setForm({
      shipmentDate: shipment.shipmentDate || "",
      noOfContainers: shipment.noOfContainers || "",
      quantity: shipment.quantity || "",
      ratePerMt: shipment.ratePerMt || "",
      purchaseRate: shipment.purchaseRate || "",
      forex: shipment.forex || "",
      freight: isFreightRequiredForShipment(shipment) ? (shipment.freight ?? "") : "",
      freightCurrency: shipment.freightCurrency || shipment.salesContract?.currencyCode || "",
      freightDescription: shipment.freightDescription || "",
      status: shipment.status || "Scheduled",
      remarks: shipment.remarks || "",
      shipmentNo: shipment.shipmentNo || ""
    });
    setErrors({});
  }

  if (!isOpen || !shipment) return null;

  const isFreightRequired = isFreightRequiredForShipment(shipment);
  const isFreightAllocated = isFreightAllocatedForShipment(shipment);

  const handleInputChange = (field, value) => {
    setForm(prev => ({ ...prev, [field]: value }));
  };

  const handleSave = async (e) => {
    e.preventDefault();

    // Validations
    const errs = {};
    if (!form.shipmentDate) errs.shipmentDate = "Shipment date is required";
    if (!form.quantity || parseFloat(form.quantity) <= 0) errs.quantity = "Quantity must be greater than 0";
    if (form.noOfContainers !== "" && parseInt(form.noOfContainers, 10) < 0) {
      errs.noOfContainers = "Containers count cannot be negative";
    }

    // Freight validation only if Freight Required = YES
    if (isFreightRequired) {
      if (form.freight !== "" && form.freight !== null && parseFloat(form.freight) < 0) {
        errs.freight = "Freight amount cannot be negative";
      }
    }

    if (Object.keys(errs).length > 0) {
      setErrors(errs);
      return;
    }

    setIsSaving(true);
    try {
      const payload = {
        shipmentDate: form.shipmentDate,
        quantity: parseFloat(form.quantity),
        noOfContainers: form.noOfContainers ? parseInt(form.noOfContainers, 10) : null,
        ratePerMt: form.ratePerMt ? parseFloat(form.ratePerMt) : null,
        purchaseRate: form.purchaseRate ? parseFloat(form.purchaseRate) : null,
        forex: form.forex ? parseFloat(form.forex) : null,
        // If Freight Required = NO: completely clear and do not save
        freight: isFreightRequired ? (form.freight !== "" && form.freight !== null ? parseFloat(form.freight) : null) : null,
        freightCurrency: isFreightRequired ? (form.freightCurrency || null) : null,
        freightDescription: isFreightRequired ? (form.freightDescription || null) : null,
        status: form.status,
        remarks: form.remarks || null,
        shipmentNo: form.shipmentNo ? parseInt(form.shipmentNo, 10) : null
      };

      const res = await shipmentsApi.updateShipment(shipment.id, payload);
      toast.success("Shipment record updated successfully");
      onSaveSuccess(res.data);
      onClose();
    } catch (err) {
      console.error(err);
      toast.error(err.response?.data?.message || "Failed to update shipment records.");
    } finally {
      setIsSaving(false);
    }
  };

  const labelCls = "block text-[11px] font-bold text-gray-500 uppercase tracking-wider mb-1.5";
  const inpCls = "w-full px-3 py-2 text-xs border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#007aff]/20 focus:border-[#007aff] bg-white transition-all";
  const errCls = "text-[10px] text-red-500 mt-1";

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/40 backdrop-blur-xs animate-in fade-in duration-200">
      <div className="bg-white rounded-2xl shadow-2xl border border-gray-100 w-full max-w-xl mx-4 overflow-hidden animate-in zoom-in-95 duration-200">
        
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100 bg-gray-50/60">
          <div>
            <h3 className="text-sm font-bold text-gray-900">Edit Shipment Operational Details</h3>
            <p className="text-[10px] text-gray-400 font-mono mt-0.5">{shipment.shipmentReference}</p>
            <BusinessReference
              reference={shipment.businessReference || shipment.businessTransaction?.businessReference}
              className="mt-1"
            />
          </div>
          <button onClick={onClose} className="p-1.5 text-gray-400 hover:text-gray-700 hover:bg-gray-100 rounded-lg transition-colors">
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Form Body */}
        <form onSubmit={handleSave}>
          <div className="p-5 max-h-[70vh] overflow-y-auto grid grid-cols-1 sm:grid-cols-2 gap-4">

            {/* Auto Route Source Mapping (Read-Only) */}
            <div className="sm:col-span-2 p-3 bg-slate-50 border border-slate-200 rounded-xl space-y-2">
              <div className="flex items-center justify-between">
                <span className="text-[11px] font-bold text-slate-700 uppercase tracking-wider">Assigned Route (Auto-Derived)</span>
                <span className="text-[10px] font-semibold text-slate-500 bg-white px-2 py-0.5 rounded border border-slate-200">Read-Only</span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs">
                <div className="p-2.5 bg-white rounded-lg border border-slate-200/80">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-[10px] font-bold text-slate-400 uppercase">Origin</span>
                    <span className="text-[9px] font-semibold text-blue-700 bg-blue-50 px-1.5 py-0.2 rounded border border-blue-200">Purchase Contract</span>
                  </div>
                  <p className="font-extrabold text-slate-900 truncate" title={shipment.origin || "—"}>
                    {shipment.origin || "—"}
                  </p>
                </div>
                <div className="p-2.5 bg-white rounded-lg border border-slate-200/80">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-[10px] font-bold text-slate-400 uppercase">Destination (Delivery Place)</span>
                    <span className="text-[9px] font-semibold text-emerald-700 bg-emerald-50 px-1.5 py-0.2 rounded border border-emerald-200">Sales Contract</span>
                  </div>
                  <p className="font-extrabold text-slate-900 truncate" title={shipment.destination || "—"}>
                    {shipment.destination || "—"}
                  </p>
                </div>
              </div>
              <p className="text-[10px] text-slate-400 italic">Origin and Destination are locked and automatically derived from source contracts.</p>
            </div>
            
            {/* Shipment Number */}
            <div>
              <label className={labelCls}>Shipment No</label>
              <input
                type="number"
                min={1}
                value={form.shipmentNo}
                onChange={(e) => handleInputChange("shipmentNo", e.target.value)}
                className={inpCls}
              />
            </div>

            {/* Status */}
            <div>
              <label className={labelCls}>Workflow Status</label>
              <div className="relative">
                <select
                  value={form.status}
                  onChange={(e) => handleInputChange("status", e.target.value)}
                  className={`${inpCls} appearance-none pr-8`}
                >
                  {WORKFLOW_STATUSES.map(s => (
                    <option key={s} value={s}>{s}</option>
                  ))}
                </select>
                <span className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">▼</span>
              </div>
            </div>

            {/* Shipment Date */}
            <div>
              <label className={labelCls}>Shipment Date <span className="text-red-500">*</span></label>
              <input
                type="date"
                value={form.shipmentDate}
                onChange={(e) => handleInputChange("shipmentDate", e.target.value)}
                className={`${inpCls} ${errors.shipmentDate ? "border-red-300" : ""}`}
              />
              {errors.shipmentDate && <p className={errCls}>{errors.shipmentDate}</p>}
            </div>

            {/* Containers */}
            <div>
              <label className={labelCls}>Containers Count</label>
              <input
                type="number"
                min={0}
                placeholder="0"
                value={form.noOfContainers}
                onChange={(e) => handleInputChange("noOfContainers", e.target.value)}
                className={`${inpCls} ${errors.noOfContainers ? "border-red-300" : ""}`}
              />
              {errors.noOfContainers && <p className={errCls}>{errors.noOfContainers}</p>}
            </div>

            {/* Quantity */}
            <div>
              <label className={labelCls}>Quantity (MT) <span className="text-red-500">*</span></label>
              <input
                type="number"
                step="0.01"
                min={0.01}
                placeholder="0.00"
                value={form.quantity}
                onChange={(e) => handleInputChange("quantity", e.target.value)}
                className={`${inpCls} ${errors.quantity ? "border-red-300" : ""}`}
              />
              {errors.quantity && <p className={errCls}>{errors.quantity}</p>}
            </div>

            {/* Rate */}
            <div>
              <label className={labelCls}>Selling Rate / MT ({shipment.salesContract?.currencyCode})</label>
              <input
                type="number"
                step="0.01"
                placeholder="0.00"
                value={form.ratePerMt}
                onChange={(e) => handleInputChange("ratePerMt", e.target.value)}
                className={inpCls}
              />
            </div>

            {/* Purchase Rate */}
            <div>
              <label className={labelCls}>Purchase Rate / MT ({shipment.salesContract?.currencyCode})</label>
              <input
                type="number"
                step="0.01"
                placeholder="0.00"
                value={form.purchaseRate}
                onChange={(e) => handleInputChange("purchaseRate", e.target.value)}
                className={inpCls}
              />
            </div>

            {/* Freight Fields - Shown only if Freight Required = YES */}
            {isFreightRequired && (
              <>
                {/* Freight Allocation */}
                <div>
                  <label className={labelCls}>Freight Allocation</label>
                  <div className="py-1">
                    <span
                      className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md border text-xs font-semibold ${
                        isFreightAllocated
                          ? "bg-green-50 text-green-700 border-green-200"
                          : "bg-red-50 text-red-700 border-red-200"
                      }`}
                      title="Freight Allocation is entirely system-driven"
                    >
                      {isFreightAllocated ? (
                        <CheckCircle2 className="h-3.5 w-3.5 text-green-600" />
                      ) : (
                        <XCircle className="h-3.5 w-3.5 text-red-600" />
                      )}
                      <span>{isFreightAllocated ? "YES" : "NO"}</span>
                    </span>
                  </div>
                </div>

                {/* Freight Amount */}
                <div>
                  <label className={labelCls}>
                    Freight Amount {form.freightCurrency ? `(${form.freightCurrency})` : ""}
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    min={0}
                    placeholder="0.00"
                    value={form.freight}
                    onChange={(e) => handleInputChange("freight", e.target.value)}
                    className={`${inpCls} ${errors.freight ? "border-red-300" : ""}`}
                  />
                  {errors.freight && <p className={errCls}>{errors.freight}</p>}
                </div>

                {/* Freight Currency */}
                <div>
                  <label className={labelCls}>Freight Currency</label>
                  <input
                    type="text"
                    maxLength={10}
                    placeholder="e.g. USD, EUR, INR"
                    value={form.freightCurrency}
                    onChange={(e) => handleInputChange("freightCurrency", e.target.value.toUpperCase())}
                    className={inpCls}
                  />
                </div>

                {/* Freight Description */}
                <div>
                  <label className={labelCls}>Freight Description</label>
                  <input
                    type="text"
                    placeholder="e.g. Ocean Freight from POL to POD"
                    value={form.freightDescription}
                    onChange={(e) => handleInputChange("freightDescription", e.target.value)}
                    className={inpCls}
                  />
                </div>
              </>
            )}

            {/* Forex */}
            <div>
              <label className={labelCls}>Forex Conversion Rate</label>
              <input
                type="number"
                step="0.01"
                placeholder="0.00"
                value={form.forex}
                onChange={(e) => handleInputChange("forex", e.target.value)}
                className={inpCls}
              />
            </div>

            {/* Remarks */}
            <div className="sm:col-span-2">
              <label className={labelCls}>Remarks</label>
              <textarea
                placeholder="Enter shipment notes, tracking details..."
                value={form.remarks}
                onChange={(e) => handleInputChange("remarks", e.target.value)}
                rows={3}
                className={`${inpCls} resize-none`}
              />
            </div>

          </div>

          {/* Footer actions */}
          <div className="flex-shrink-0 px-5 py-4 border-t border-gray-100 bg-gray-50/60 flex items-center justify-end gap-2">
            <button
              type="button"
              onClick={onClose}
              disabled={isSaving}
              className="px-4 py-2 text-xs font-semibold text-gray-600 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 transition-all cursor-pointer disabled:opacity-50"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isSaving}
              className="px-4 py-2 text-xs font-semibold text-white bg-[#007aff] hover:bg-blue-600 rounded-xl flex items-center gap-1.5 shadow-sm shadow-blue-500/10 transition-all cursor-pointer disabled:opacity-50"
            >
              {isSaving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Check className="h-3.5 w-3.5" />}
              Save Changes
            </button>
          </div>
        </form>

      </div>
    </div>
  );
}
